import type { IssueId } from "@/types/common";

/**
 * Raised when placing or moving an issue would make the sub-issue tree loop
 * back on itself, or would push a descendant deeper than
 * `MAX_SUB_ISSUE_DEPTH` allows.
 */
export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: "cycle" | "too_deep",
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or one of its own sub-issues.`
        : `Issue ${issueId} would sit deeper than the sub-issue depth limit allows.`,
    );
    this.name = "IssueHierarchyError";
  }
}

void (null as unknown as IssueId);

