/** Direct children of `parentId`, every archive status, unsorted. */
async function findChildren(
  orgId: OrgId,
  parentId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.parentId, parentId)),
    )
    .all();
  return rows.map((row) => toIssue(row));
}

/** The direct, non-archived sub-issues of `issueId`, oldest first. */
export async function listSubIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.parentId, issueId),
        isNull(issues.archivedAt),
      ),
    )
    .orderBy(issues.createdAt, issues.number)
    .all();
  return rows.map((row) => toIssue(row));
}

/** Every issue below `issueId`, at any depth, regardless of archive status. */
async function listAllDescendants(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const result: Issue[] = [];
  let frontier: readonly IssueId[] = [issueId];

  while (frontier.length > 0) {
    const children = (
      await Promise.all(frontier.map((id) => findChildren(orgId, id)))
    ).flat();
    if (children.length === 0) break;
    result.push(...children);
    frontier = children.map((child) => child.id);
  }

  return result;
}

/** Walks the parent chain upward from `issueId`, counting edges to the root. */
export async function getIssueLevel(
  orgId: OrgId,
  issueId: IssueId,
): Promise<number> {
  let level = 0;
  let current = await findIssueById(orgId, issueId);

  while (current?.parentId != null) {
    level += 1;
    current = await findIssueById(orgId, current.parentId);
  }

  return level;
}

/** True when `candidateId` is `issueId` itself, or sits below it in the tree. */
export async function isSelfOrDescendant(
  orgId: OrgId,
  issueId: IssueId,
  candidateId: IssueId,
): Promise<boolean> {
  let current: IssueId | null = candidateId;

  while (current !== null) {
    if (current === issueId) return true;
    const row = await findIssueById(orgId, current);
    current = row?.parentId ?? null;
  }

  return false;
}

/** Edges from `issueId` down to its deepest descendant; 0 when it has none. */
export async function getSubtreeHeight(
  orgId: OrgId,
  issueId: IssueId,
): Promise<number> {
  const children = await findChildren(orgId, issueId);
  if (children.length === 0) return 0;

  const childHeights = await Promise.all(
    children.map((child) => getSubtreeHeight(orgId, child.id)),
  );
  return 1 + Math.max(...childHeights);
}

export async function setIssueParent(
  orgId: OrgId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ parentId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

/** Counts, over every non-archived issue below `issueId` at any depth. */
export async function getIssueRollup(
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  const descendants = (await listAllDescendants(orgId, issueId)).filter(
    (issue) => issue.archivedAt === null,
  );

  const closed = descendants.filter((issue) =>
    CLOSED_ISSUE_STATUSES.includes(issue.status),
  ).length;

  return {
    total: descendants.length,
    open: descendants.length - closed,
    closed,
  };
}

/** Live issues below `issueId`, at any depth; drives cascade archiving. */
export async function listLiveDescendants(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  return (await listAllDescendants(orgId, issueId)).filter(
    (issue) => issue.archivedAt === null,
  );
}

