/**
 * Archiving cascades: every live issue below the target, at any depth, is
 * archived along with it, each announced with its own `issue.archived` event
 * so everything downstream (counters, search, alerts) follows for all of
 * them. Issues already archived are left untouched.
 */
export async function archiveIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const descendants = await issueRepo.listLiveDescendants(orgId, issueId);

  const archived = await issueRepo.archiveIssue(orgId, issueId);

  await emit("issue.archived", {
    ...actorEnvelope(actor),
    issueId: archived.id,
    projectId: archived.projectId,
    parentId: archived.parentId,
    wasOpen: !CLOSED_ISSUE_STATUSES.includes(issue.status),
  });

  for (const descendant of descendants) {
    const archivedDescendant = await issueRepo.archiveIssue(
      orgId,
      descendant.id,
    );
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: archivedDescendant.id,
      projectId: archivedDescendant.projectId,
      parentId: archivedDescendant.parentId,
      wasOpen: !CLOSED_ISSUE_STATUSES.includes(descendant.status),
    });
  }

  return archived;
}

