  assertNotArchived("Issue", issue.id, issue);

  const descendants = await issueRepo.listLiveDescendants(orgId, issueId);

  const archived = await issueRepo.archiveIssue(orgId, issueId);

  await emit("issue.archived", {
    ...actorEnvelope(actor),
    issueId: archived.id,
    projectId: archived.projectId,
    parentId: archived.parentId,
    wasOpen: !CLOSED_ISSUE_STATUSES.includes(issue.status),
  });

  for (const descendant of descendants) {
    const archivedDescendant = await issueRepo.archiveIssue(
      orgId,
      descendant.id,
    );
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: archivedDescendant.id,
      projectId: archivedDescendant.projectId,
      parentId: archivedDescendant.parentId,
      wasOpen: !CLOSED_ISSUE_STATUSES.includes(descendant.status),
    });
  }

  return archived;
}

