/**
 * A sub-issue just stopped being open. Tells the direct parent's assignee,
 * once, when that leaves the parent with no open issue below it at any
 * depth. Skipped when there is no parent, no assignee, or the parent is
 * archived.
 */
async function notifyParentWhenFullyClosed(
  orgId: OrgId,
  parentId: IssueId | null,
  actorId: UserId | null,
): Promise<void> {
  if (parentId === null) return;

  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (!parent || parent.archivedAt !== null || parent.assigneeId === null) {
    return;
  }

  const rollup = await issueRepo.getIssueRollup(orgId, parentId);
  if (rollup.open > 0) return;

  await notify(orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "All sub-issues are closed",
    body: `Every sub-issue below ${parentId} is now closed`,
    href: `/issues/${parentId}`,
    actorId,
  });
}

registerFanOut();

